import { existsSync } from "node:fs";
import fs from "node:fs/promises";
import path from "node:path";
import { setTimeout } from "node:timers/promises";
import {
  AgentSideConnection,
  ndJsonStream,
  PROTOCOL_VERSION,
  RequestError,
  type Agent,
  type SessionConfigOption,
} from "@agentclientprotocol/sdk";

const [directory, route] = process.argv.slice(2);
if (!directory || !route) {
  throw new Error("Expected barrier directory and model route");
}
let model = "default-model";
let mode = "auto";
let effort = "low";
let controlCount = 0;

function modelIds(): string[] {
  return existsSync(path.join(directory, "parameterized-models"))
    ? [
        "default-model",
        "selected[fast=true]",
        "provider/selected[fast=true]",
        ...(existsSync(path.join(directory, "ambiguous-models")) ? ["selected[fast=false]"] : []),
      ]
    : ["default-model", "first-model", "second-model"];
}

function configOptions(): SessionConfigOption[] {
  return [
    ...(route === "config" && !existsSync(path.join(directory, "remove-model-control"))
      ? [
          {
            id: "llm",
            name: "Model",
            category: "model",
            type: "select" as const,
            currentValue: model,
            options: modelIds().map((value) => ({
              value,
              name: value,
            })),
          },
        ]
      : []),
    {
      id: "effort",
      name: "Effort",
      type: "select",
      currentValue: effort,
      options: ["low", "high"].map((value) => ({ value, name: value })),
    },
  ];
}

function sessionState() {
  return {
    configOptions: configOptions(),
    modes: {
      currentModeId: mode,
      availableModes: [
        "auto",
        ...(existsSync(path.join(directory, "retired-plan")) ? [] : ["plan"]),
      ].map((id) => ({ id, name: id })),
    },
    ...(route === "legacy"
      ? {
          models: {
            currentModelId: model,
            availableModels: modelIds().map((modelId) => ({
              modelId,
              name: modelId,
            })),
          },
        }
      : {}),
  };
}

async function control(method: string, value: string, apply: () => void) {
  const sequence = ++controlCount;
  const entry = JSON.stringify({ sequence, method, value }) + "\n";
  await fs.appendFile(path.join(directory, "received.jsonl"), entry);
  await fs.writeFile(path.join(directory, `received-${sequence}`), "received");
  if (existsSync(path.join(directory, "disconnect-control"))) {
    process.exit(23);
  }
  if (sequence === 1 && existsSync(path.join(directory, "hold-first"))) {
    while (!existsSync(path.join(directory, "release-first"))) {
      await setTimeout(5);
    }
  }
  if (existsSync(path.join(directory, "hold-control"))) {
    while (!existsSync(path.join(directory, "release-control"))) {
      await setTimeout(5);
    }
  }
  apply();
  await fs.appendFile(path.join(directory, "effects.jsonl"), entry);
}

const agent: Agent = {
  async initialize() {
    return {
      protocolVersion: PROTOCOL_VERSION,
      agentCapabilities: {
        loadSession: !existsSync(path.join(directory, "no-load")),
        sessionCapabilities: { close: {} },
      },
      authMethods: [],
    };
  },
  async authenticate() {},
  async newSession() {
    await fs.appendFile(path.join(directory, "sessions.jsonl"), '"new"\n');
    if (existsSync(path.join(directory, "hold-new"))) {
      await fs.writeFile(path.join(directory, "new-started"), "started");
      while (!existsSync(path.join(directory, "release-new"))) {
        await setTimeout(5);
      }
    }
    return { sessionId: "authority-session", ...sessionState() };
  },
  async loadSession() {
    await fs.appendFile(path.join(directory, "sessions.jsonl"), '"load"\n');
    if (existsSync(path.join(directory, "hold-load"))) {
      await fs.writeFile(path.join(directory, "load-started"), "started");
      while (!existsSync(path.join(directory, "release-load"))) {
        await setTimeout(5);
      }
    }
    return sessionState();
  },
  async prompt({ sessionId, prompt }) {
    if (prompt.some((part) => part.type === "text" && part.text === "refresh-models")) {
      await connection.sessionUpdate({
        sessionId,
        update: { sessionUpdate: "config_option_update", configOptions: configOptions() },
      });
    }
    const entry = JSON.stringify({ sessionId, prompt }) + "\n";
    await fs.appendFile(path.join(directory, "prompts.jsonl"), entry);
    await fs.writeFile(path.join(directory, "prompt-started"), "started");
    while (!existsSync(path.join(directory, "release-prompt"))) {
      await setTimeout(5);
    }
    if (existsSync(path.join(directory, "emit-final-state"))) {
      await connection.sessionUpdate({
        sessionId,
        update: {
          sessionUpdate: "agent_message_chunk",
          content: { type: "text", text: "final answer while control waits" },
        },
      });
      await connection.sessionUpdate({
        sessionId,
        update: {
          sessionUpdate: "available_commands_update",
          availableCommands: [{ name: "after-control", description: "Final command metadata" }],
        },
      });
      await connection.sessionUpdate({
        sessionId,
        update: {
          sessionUpdate: "usage_update",
          used: 12,
          size: 500,
          _meta: { usage: { input_tokens: 9, output_tokens: 3, total_tokens: 12 } },
        },
      });
    }
    await fs.appendFile(path.join(directory, "prompt-effects.jsonl"), entry);
    return { stopReason: "end_turn" };
  },
  async cancel() {},
  async closeSession() {
    await fs.appendFile(path.join(directory, "sessions.jsonl"), '"close"\n');
    return {};
  },
  async setSessionMode({ modeId }) {
    await control("session/set_mode", modeId, () => {
      if (
        (modeId === "plan" && existsSync(path.join(directory, "retired-plan"))) ||
        (modeId === "auto" && existsSync(path.join(directory, "reject-auto")))
      ) {
        throw RequestError.invalidParams({ modeId });
      }
      mode = modeId;
    });
    return {};
  },
  async setSessionConfigOption({ configId, value }) {
    if (typeof value !== "string") {
      throw new Error("Expected string config value");
    }
    await control("session/set_config_option", value, () => {
      if (configId === "llm") {
        model = value;
        if (existsSync(path.join(directory, "parameterized-models"))) {
          effort = "low";
        }
      } else {
        effort = value;
      }
    });
    return { configOptions: configOptions() };
  },
  async extMethod(method, params) {
    const modelId = params.modelId;
    if (method !== "session/set_model" || typeof modelId !== "string") {
      throw new Error("Unsupported control request");
    }
    await control("session/set_model", modelId, () => {
      model = modelId;
    });
    return {};
  },
};

const input = new ReadableStream<Uint8Array>({
  start(controller) {
    process.stdin.on("data", (chunk: Buffer) => controller.enqueue(chunk));
    process.stdin.once("end", () => controller.close());
    process.stdin.once("error", (error: Error) => controller.error(error));
  },
  cancel() {
    process.stdin.destroy();
  },
});
const output = new WritableStream<Uint8Array>({
  write(chunk) {
    return new Promise<void>((resolve, reject) => {
      process.stdout.write(chunk, (error) => {
        if (error) {
          reject(error);
        } else {
          resolve();
        }
      });
    });
  },
});
const connection = new AgentSideConnection(() => agent, ndJsonStream(output, input));
await connection.closed;

import assert from "node:assert/strict";
import test from "node:test";
import {
  assertRequestedModelSupported,
  isRequestedModelUnsupportedError,
  modelStateFromConfigOptions,
  REQUESTED_MODEL_UNSUPPORTED_ERROR_CODE,
  RequestedModelUnsupportedError,
} from "../src/acp/model-support.js";

function modelSelect(id: string, category?: string) {
  return {
    id,
    name: id,
    type: "select",
    category,
    currentValue: `${id}-first`,
    options: [{ value: `${id}-first`, name: `${id} first` }],
  };
}

test("model config selection distinguishes a categorized model from provider controls", () => {
  const provider = modelSelect("provider", "model");
  const model = modelSelect("model", "model");
  for (const options of [
    [provider, model],
    [model, provider],
  ]) {
    assert.deepEqual(modelStateFromConfigOptions(options), {
      configId: "model",
      currentModelId: "model-first",
      availableModels: [{ modelId: "model-first", name: "model first" }],
    });
  }
});

test("model config selection preserves categorized custom controls ahead of legacy ids", () => {
  const custom = modelSelect("llm", "model");
  for (const category of [undefined, "mode"]) {
    const legacy = modelSelect("model", category);
    for (const options of [
      [legacy, custom],
      [custom, legacy],
    ]) {
      assert.equal(modelStateFromConfigOptions(options)?.configId, "llm");
    }
  }
  assert.equal(modelStateFromConfigOptions([modelSelect("model")])?.configId, "model");
  assert.equal(
    modelStateFromConfigOptions([custom, modelSelect("other", "model")])?.configId,
    "llm",
  );
});

test("model config selection skips malformed preferred controls and retains grouped models", () => {
  const custom = modelSelect("llm", "model");
  const malformed = { ...modelSelect("model", "model"), options: null };
  assert.equal(modelStateFromConfigOptions([malformed, custom])?.configId, "llm");
  const grouped = {
    ...modelSelect("model", "model"),
    options: [{ group: "group", name: "Group", options: modelSelect("model").options }],
  };
  assert.equal(modelStateFromConfigOptions([custom, grouped])?.configId, "model");
  assert.deepEqual(modelStateFromConfigOptions([custom, grouped])?.availableModels, [
    { modelId: "model-first", name: "model first" },
  ]);
});

test("Claude ACP model validation warns for unadvertised selectors", () => {
  const warning = assertRequestedModelSupported({
    requestedModel: "opus[1m]",
    models: {
      configId: "model",
      currentModelId: "sonnet",
      availableModels: [
        { modelId: "default", name: "Default" },
        { modelId: "sonnet", name: "Sonnet" },
      ],
    },
    agentCommand: "npx -y @agentclientprotocol/claude-agent-acp@^0.76.0",
    context: "apply",
  });

  assert.match(
    warning ?? "",
    /requested model "opus\[1m\]" was not in the Claude ACP advertised model list/,
  );
});

test("non-Claude model validation rejects unadvertised selectors", () => {
  assert.throws(() => {
    try {
      assertRequestedModelSupported({
        requestedModel: "missing-model",
        models: {
          configId: "model",
          currentModelId: "default",
          availableModels: [{ modelId: "default", name: "Default" }],
        },
        agentCommand: "mock-agent --advertise-models",
        context: "apply",
      });
    } catch (error) {
      assert(error instanceof RequestedModelUnsupportedError);
      assert.equal(error.code, REQUESTED_MODEL_UNSUPPORTED_ERROR_CODE);
      assert.equal(error.reason, "unadvertised-model");
      assert.equal(isRequestedModelUnsupportedError(error), true);
      assert.equal(
        isRequestedModelUnsupportedError({
          name: "RequestedModelUnsupportedError",
          code: REQUESTED_MODEL_UNSUPPORTED_ERROR_CODE,
          reason: "unadvertised-model",
        }),
        true,
      );
      throw error;
    }
  }, /did not advertise that model/);
});

test("model validation distinguishes missing model capability", () => {
  assert.throws(
    () =>
      assertRequestedModelSupported({
        requestedModel: "missing-model",
        models: undefined,
        agentCommand: "mock-agent",
        context: "apply",
      }),
    (error: unknown) => {
      assert(error instanceof RequestedModelUnsupportedError);
      assert.equal(error.reason, "missing-capability");
      assert.equal(isRequestedModelUnsupportedError(error), true);
      return error.message.includes("did not advertise model support");
    },
  );
});

test("model unsupported predicate rejects unrelated errors", () => {
  assert.equal(isRequestedModelUnsupportedError(new Error("did not advertise that model")), false);
  assert.equal(
    isRequestedModelUnsupportedError({
      name: "RequestedModelUnsupportedError",
      code: "ACP_TURN_FAILED",
      reason: "missing-capability",
    }),
    false,
  );
  assert.equal(
    isRequestedModelUnsupportedError({
      name: "RequestedModelUnsupportedError",
      code: REQUESTED_MODEL_UNSUPPORTED_ERROR_CODE,
      reason: "unknown",
    }),
    false,
  );
});

test("Cursor model validation accepts a unique advertised suffix variant", () => {
  const warning = assertRequestedModelSupported({
    requestedModel: "composer-2.5",
    models: {
      configId: "model",
      currentModelId: "composer-2.5[fast=false]",
      availableModels: [{ modelId: "composer-2.5[fast=false]", name: "Composer 2.5" }],
    },
    agentCommand: "cursor-agent acp",
    context: "apply",
  });

  assert.match(warning ?? "", /advertised "composer-2\.5\[fast=false\]"/);
});

test("Cursor model validation keeps ambiguous suffix variants strict", () => {
  assert.throws(
    () =>
      assertRequestedModelSupported({
        requestedModel: "provider/composer-2.5",
        models: {
          configId: "model",
          currentModelId: "provider/composer-2.5[fast=false]",
          availableModels: [
            { modelId: "provider/composer-2.5[fast=false]", name: "Composer 2.5" },
            { modelId: "provider/composer-2.5[fast=true]", name: "Composer 2.5 Fast" },
            { modelId: "composer-2.5[fast=true]", name: "Other model family" },
          ],
        },
        agentCommand: "cursor-agent acp",
        context: "apply",
      }),
    (error: unknown) => {
      assert.ok(isRequestedModelUnsupportedError(error));
      assert.equal(error.reason, "unadvertised-model");
      assert.equal(error.ambiguous, true);
      return true;
    },
  );
});

test("Cursor model resolution preserves an exact advertised id", () => {
  const warning = assertRequestedModelSupported({
    requestedModel: "composer-2.5",
    models: {
      configId: "model",
      currentModelId: "composer-2.5",
      availableModels: [
        { modelId: "composer-2.5", name: "Composer 2.5" },
        { modelId: "composer-2.5[fast=false]", name: "Composer 2.5 Fast" },
      ],
    },
    agentCommand: "cursor-agent acp",
    context: "apply",
  });

  assert.equal(warning, undefined);
});

import { appendFileSync } from "node:fs";
import readline from "node:readline";

type Request = {
  id?: string | number;
  method?: string;
  params?: { cwd?: unknown; sessionId?: unknown; prompt?: unknown };
};

const [bootPath, tracePath] = process.argv.slice(2);
if (!bootPath || !tracePath) {
  throw new Error("Expected boot marker and wire trace paths");
}
appendFileSync(bootPath, JSON.stringify({ pid: process.pid, event: "boot" }) + "\n");
const record = (direction: "in" | "out", raw: string) =>
  appendFileSync(tracePath, JSON.stringify({ pid: process.pid, direction, raw }) + "\n");
const send = (message: object) => {
  const raw = JSON.stringify(message);
  record("out", raw);
  process.stdout.write(raw + "\n");
};
const result = (id: Request["id"], value: object) => send({ jsonrpc: "2.0", id, result: value });
const failure = (id: Request["id"], message: string) =>
  send({ jsonrpc: "2.0", id, error: { code: -32602, message } });

function isTextBlock(value: unknown): boolean {
  return (
    value !== null &&
    typeof value === "object" &&
    "type" in value &&
    value.type === "text" &&
    "text" in value &&
    typeof value.text === "string"
  );
}

for await (const raw of readline.createInterface({ input: process.stdin })) {
  record("in", raw);
  const request = JSON.parse(raw) as Request;
  const params = request.params ?? {};
  if (request.method === "initialize") {
    result(request.id, { protocolVersion: 1, agentCapabilities: {} });
  } else if (request.method === "session/new") {
    if (typeof params.cwd !== "string") {
      failure(request.id, "Invalid cwd parameter");
    } else {
      result(request.id, { sessionId: "synthetic-session" });
    }
  } else if (request.method === "session/prompt") {
    if (typeof params.sessionId !== "string") {
      failure(request.id, "Invalid session id");
    } else if (!Array.isArray(params.prompt) || !params.prompt.every(isTextBlock)) {
      failure(request.id, "Invalid prompt content");
    } else {
      send({
        jsonrpc: "2.0",
        method: "session/update",
        params: {
          sessionId: params.sessionId,
          update: {
            sessionUpdate: "agent_message_chunk",
            content: { type: "text", text: "Synthetic response" },
          },
        },
      });
      result(request.id, { stopReason: "end_turn" });
    }
  } else if (request.method !== "session/cancel" && request.id !== undefined) {
    send({ jsonrpc: "2.0", id: request.id, error: { code: -32601, message: "Unknown method" } });
  }
}

import assert from "node:assert/strict";
import test from "node:test";
import { promptForPermission } from "../src/permission-prompt.js";
import { withCapturedStderrWrites, withMockedReadline, withTtyState } from "./tty-test-helpers.js";

for (const answer of ["n", "yes"]) {
  test(`permission controls remain visible with answer ${answer}`, async () => {
    const options = Object.freeze({
      header: "[permission] Allow write to notes\rHIDDEN.txt?",
      details: "first\r\u001b[1Ahidden\nsecond\tline\u007f\u009f",
      prompt: '\n[permission] Allow command "echo\r\u001b[2Khidden\nnext"? (y/N) ',
    });
    await withTtyState({ stdin: true, stderr: true }, async () => {
      await withCapturedStderrWrites(async (writes) => {
        await withMockedReadline(
          () => ({
            question: async (prompt) => {
              writes.push(prompt);
              return answer;
            },
            close: () => {},
          }),
          async () => {
            assert.equal(await promptForPermission(options), answer === "yes");
          },
        );
        assert.deepEqual(writes, [
          "\n[permission] Allow write to notes\\x0dHIDDEN.txt?\n",
          "first\\x0d\\x1b[1Ahidden\nsecond\\x09line\\x7f\\x9f\n",
          '\n[permission] Allow command "echo\\x0d\\x1b[2Khidden\\x0anext"? (y/N) ',
        ]);
      });
    });
    assert.equal(options.header, "[permission] Allow write to notes\rHIDDEN.txt?");
  });
}

test("permission rendering preserves ordinary Unicode text", async () => {
  await withTtyState({ stdin: true, stderr: true }, async () => {
    await withMockedReadline(
      () => ({
        question: async (prompt) => {
          assert.equal(prompt, "Allow café 🦞? ");
          return "n";
        },
        close: () => {},
      }),
      async () => {
        assert.equal(await promptForPermission({ prompt: "Allow café 🦞? " }), false);
      },
    );
  });
});

import assert from "node:assert/strict";
import test from "node:test";
import { AcpClient } from "../src/acp/client.js";
import { DISCARD_OUTPUT_FORMATTER } from "../src/session/execution/discard-output.js";
import { runOnce } from "../src/session/execution/runtime.js";
import type { PermissionStats } from "../src/types.js";

function gate() {
  let release = () => {};
  const promise = new Promise<void>((resolve) => {
    release = resolve;
  });
  return { promise, release };
}

function recordPermission(client: AcpClient, decision: "approved" | "denied" | "cancelled") {
  // Keep the real counter and snapshot getter; only transport/lifecycle work is stubbed.
  (
    client as unknown as {
      recordPermissionDecision(value: "approved" | "denied" | "cancelled"): void;
    }
  ).recordPermissionDecision(decision);
}

const beforeClose: PermissionStats = { requested: 3, approved: 1, denied: 1, cancelled: 1 };
const afterClose: PermissionStats = { requested: 4, approved: 1, denied: 1, cancelled: 2 };

for (const outcome of ["success", "prompt", "close", "prompt-and-close", "flush"] as const) {
  test(
    `runOnce final permission observer preserves the ${outcome} outcome and flush ordering`,
    { timeout: 5_000 },
    async (t) => {
      const closeEntered = gate();
      const releaseClose = gate();
      const trace: string[] = [];
      const snapshots: PermissionStats[] = [];
      const observerArguments: PermissionStats[] = [];
      const promptFailure = new Error("original prompt failure");
      const closeFailure = new Error("original close failure");
      const flushFailure = new Error("original flush failure");
      const observerFailure = new Error("permission observer failure");
      const meta = { fixture: "permission-lifecycle" };
      let closeCalls = 0;
      let flushCalls = 0;
      let settled = false;

      t.signal.addEventListener("abort", releaseClose.release, { once: true });
      const startMock = t.mock.method(AcpClient.prototype, "start", async () => {});
      t.mock.method(AcpClient.prototype, "createSession", async () => ({
        sessionId: "permission-lifecycle-session",
        configOptionsPresent: false,
        legacyModelMetadataPresent: false,
      }));
      t.mock.method(AcpClient.prototype, "prompt", async function (this: AcpClient) {
        recordPermission(this, "approved");
        recordPermission(this, "denied");
        recordPermission(this, "cancelled");
        if (outcome === "prompt" || outcome === "prompt-and-close") {
          throw promptFailure;
        }
        return { stopReason: "end_turn", _meta: meta };
      });
      t.mock.method(AcpClient.prototype, "close", async function (this: AcpClient) {
        closeCalls += 1;
        trace.push("close:entered");
        closeEntered.release();
        await releaseClose.promise;
        // A pending permission can finish cancellation while its owner retires.
        recordPermission(this, "cancelled");
        trace.push("close:settled");
        if (outcome === "close" || outcome === "prompt-and-close") {
          throw closeFailure;
        }
      });

      const running = runOnce(
        {
          agentCommand: "unused-permission-lifecycle-peer",
          cwd: process.cwd(),
          prompt: [{ type: "text", text: "synthetic permission lifecycle" }],
          permissionMode: "deny-all",
          promptRetries: 0,
          outputFormatter: {
            ...DISCARD_OUTPUT_FORMATTER,
            flush() {
              flushCalls += 1;
              trace.push("flush");
              if (outcome === "flush") {
                throw flushFailure;
              }
            },
          },
          onPermissionStats(stats) {
            trace.push("stats");
            snapshots.push({ ...stats });
            observerArguments.push(stats);
            Object.assign(stats, { requested: 99, approved: 99, denied: 99, cancelled: 99 });
            throw observerFailure;
          },
        },
        { signal: new AbortController().signal, handleProcessInterrupts: false },
      ).then(
        (value) => {
          settled = true;
          return { ok: true as const, value };
        },
        (error: unknown) => {
          settled = true;
          return { ok: false as const, error };
        },
      );

      try {
        await closeEntered.promise;
        const client: unknown = startMock.mock.calls[0]?.this;
        assert.ok(client instanceof AcpClient);
        assert.deepEqual(client.getPermissionStats(), beforeClose);
        assert.deepEqual(trace, ["close:entered"]);
        assert.deepEqual(snapshots, [], "the observer must wait for owned cleanup to settle");
        assert.equal(flushCalls, 0);
        assert.equal(settled, false);

        releaseClose.release();
        const result = await running;
        assert.deepEqual(trace, ["close:entered", "close:settled", "stats", "flush"]);
        assert.equal(closeCalls, 1);
        assert.equal(flushCalls, 1);
        assert.deepEqual(
          snapshots,
          [afterClose],
          "exactly one final snapshot includes cleanup decisions",
        );
        assert.equal(observerArguments.length, 1);
        assert.deepEqual(
          client.getPermissionStats(),
          afterClose,
          "observer mutation must not change client counters",
        );

        if (outcome === "success") {
          assert.equal(result.ok, true);
          if (result.ok) {
            assert.equal(result.value.stopReason, "end_turn");
            assert.equal(result.value.sessionId, "permission-lifecycle-session");
            assert.equal(result.value._meta, meta);
            assert.deepEqual(result.value.permissionStats, beforeClose);
            assert.notEqual(result.value.permissionStats, observerArguments[0]);
          }
        } else {
          assert.equal(result.ok, false);
          if (!result.ok) {
            const expected =
              outcome === "flush"
                ? flushFailure
                : outcome === "close" || outcome === "prompt-and-close"
                  ? closeFailure
                  : promptFailure;
            assert.equal(
              result.error,
              expected,
              "the observer must not replace the original outcome",
            );
          }
        }
      } finally {
        releaseClose.release();
        await running;
        t.signal.removeEventListener("abort", releaseClose.release);
      }
    },
  );
}

import assert from "node:assert/strict";
import fs from "node:fs/promises";
import os from "node:os";
import path from "node:path";
import test, { type TestContext } from "node:test";
import { fileURLToPath } from "node:url";
import { AcpClient } from "../src/acp/client.js";
