async function runPromptProcess(
  t: TestContext,
  body: string,
  onStderr: (output: string, child: ChildProcessWithoutNullStreams) => void,
): Promise<{ stdout: string; stderr: string }> {
  const target = new URL("../src/permission-prompt.js", import.meta.url).href;
  const script = `
    import { promptForPermission } from ${JSON.stringify(target)};
    import { getEventListeners } from 'node:events';
    Object.defineProperty(process.stdin, 'isTTY', { value: true });
    Object.defineProperty(process.stderr, 'isTTY', { value: true });
    ${body}
  `;
  const child = spawn(process.execPath, ["--input-type=module", "--eval", script], {
    stdio: ["pipe", "pipe", "pipe"],
  });
  const closed = once(child, "close");
  t.after(async () => {
    if (child.exitCode === null && child.signalCode === null) {
      child.kill("SIGKILL");
    }
    await closed;
  });
  let stderr = "";
  let stdout = "";
  child.stderr.setEncoding("utf8").on("data", (chunk: string) => {
    stderr += chunk;
    onStderr(stderr, child);
  });
  child.stdout.setEncoding("utf8").on("data", (chunk: string) => {
    stdout += chunk;
  });
  const [code] = await closed;
  assert.equal(code, 0, stderr);
  return { stdout, stderr };
}

import assert from "node:assert/strict";
import os from "node:os";
import test from "node:test";
import { buildAgentSpawnOptions } from "../src/acp/auth-env.js";

function buildSyntheticAuthEnvironment(
  platform: NodeJS.Platform,
  inherited: NodeJS.ProcessEnv,
  credentials?: Record<string, string>,
  sessionEnv?: Record<string, string>,
  runtimeEnv?: Record<string, string>,
): NodeJS.ProcessEnv {
  const originalEnvironment = process.env;
  const platformDescriptor = Object.getOwnPropertyDescriptor(process, "platform");
  const parentEnvironment = { ...inherited };
  process.env = parentEnvironment;
  Object.defineProperty(process, "platform", { value: platform });
  try {
    const options = buildAgentSpawnOptions(os.tmpdir(), credentials, sessionEnv, runtimeEnv);
    assert.equal(process.env, parentEnvironment);
    assert.deepEqual(parentEnvironment, inherited);
    return options.env;
  } finally {
    process.env = originalEnvironment;
    if (platformDescriptor) {
      Object.defineProperty(process, "platform", platformDescriptor);
    }
  }
}

