    const admitted = new Promise<void>((resolve) => {
      markAdmitted = resolve;
    });
    const input = {
      handle,
      model: "second-model",
      signal: cancelled.signal,
      assertActive: markAdmitted,
    };
    const pending = runtime.setModel(input).then(
      () => undefined,
